// Mitigation Library detail columns (H–L) for the reference tab, keyed by library id.
// Source: CHAI Risk Mitigation Mapping workbook (v7, Oct 2026).

export interface MitigationDetail { persona: string; notes: string; solutionTypes: string; lifecycle: string; responsible: string }

export const MITIGATION_DETAILS: Record<string, MitigationDetail> = {
  'M09': { persona: 'Privacy & Compliance function (e.g., Privacy Officer, Compliance Officer, HIM Manager; in smaller organizations a CMIO, CIO, or informatics lead often wears this hat), with Data Governance, the Business or Clinical Owner, and AI Governance', notes: 'Aligns with the HIPAA minimum-necessary principle. Example in practice: one health system applies data minimization during AI intake by confirming the specific data elements needed for the intended use case, limiting PHI/PII exposure where possible, and reviewing whether prompts, outputs, logs, and vendor-accessible data are actually necessary for the stated purpose. Define key terms (e.g., \'minimum necessary\', \'exposure\', \'vendor-accessible data\') in the governance policy so the control can be applied consistently.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Deployment; Monitoring; Termination', responsible: 'Shared — health system defines the minimum data set and reviews data flows; vendor must configure the product to request/retain only that data' },
  'M10': { persona: 'Information Security / Identity & Access Management function, with the Application Owner, Data Owner, and AI Governance', notes: 'Example in practice: one health system expects access controls for AI systems to cover users, privileged administrators, service accounts, APIs, and any non-human or agentic access, with access that is role-based, least-privilege, and periodically reviewed. Where AI agents act on behalf of users, associate each agent call with both the requesting user identity and a unique agent identity (see M17, M29).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Deployment; Monitoring; Termination', responsible: 'Shared — health system owns role definitions and access reviews; vendor must support granular roles and non-human identity controls in the product' },
  'M29': { persona: 'Information Security / Identity & Access Management function, with the Infrastructure/Platform Owner and Application Owner', notes: 'Example in practice: one health system associates every agentic AI call with a unique agent identity (e.g., a UUID) paired with the requesting user ID, set up via an API gateway and custom headers, so it can trace which user and which agent made each request. Another routes all agentic requests through an approved API gateway that ties each interaction to an authenticated user identity for policy enforcement and auditability.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Deployment; Monitoring; Termination', responsible: 'Shared — health system enforces identity standards (SSO/MFA, access reviews); vendor must integrate with them and support non-human identity management' },
  'M30': { persona: 'Information Security function, with Cloud/Infrastructure or Platform Engineering; Vendor Management when the solution is third-party hosted', notes: 'Encryption is necessary but not sufficient unless the control specifies what is in scope and who owns it. Responsibility shifts depending on whether data is hosted inside or outside the health system\'s network; for vendor-hosted solutions, verify encryption standards and key management through the vendor risk assessment (M25) and contract/BAA terms.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Deployment; Monitoring; Termination', responsible: 'Shared — vendor implements encryption for hosted components; health system verifies standards, manages its own keys/endpoints, and covers on-premises components' },
  'M31': { persona: 'Privacy & Compliance function (e.g., Privacy Officer, Compliance Officer, CIO in smaller organizations), with Data Governance, Legal, and the Data Owner', notes: 'HHS recognizes both Safe Harbor and Expert Determination (M71) as HIPAA de-identification methods. This control may be difficult for tools working directly in patient care; apply it \'as able\' and document why identifiers are needed when they are. Shifting or offsetting identifiers (e.g., date shifting) is another option to reduce risk when full removal is not feasible.', solutionTypes: 'Clinical; Operational; Administrative; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Deployment; Termination', responsible: 'Shared — health system decides when de-identification is required and validates it; vendor must support de-identified data flows or document why identifiers are needed' },
  'M32': { persona: 'Data Science / Analytics function (in smaller organizations this may be Clinical Informatics, an IT analyst, or Business Intelligence), with Privacy, Data Governance, and AI Governance; Vendor Management when synthetic data is vendor-supplied', notes: 'Apply \'when able\' — smaller hospitals report that synthetic data and benchmarks are scarce and hard to produce. Example in practice: one health system has developed (and plans to publish) a series of synthetic benchmarks for detecting harmful language in free-text notes, used to evaluate and compare models.', solutionTypes: 'Clinical; Operational; Administrative; Research', lifecycle: 'Pre-deployment; Piloting', responsible: 'Shared — typically vendor or developer generates; health system validates privacy risk and utility before relying on it' },
  'M33': { persona: 'Privacy function, with Data Engineering, Data Governance, and AI/ML Engineering', notes: 'The term \'anonymization\' is used inconsistently; this control is distinct from HIPAA Safe Harbor (M31) and Expert Determination (M71) and is framed as a technical preprocessing step. Few health systems train models locally, so in practice this most often applies to fine-tuning, retrieval corpora, prompts, and data sent to vendor-hosted models.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment', responsible: 'Shared — vendor for models it trains; health system for any local data it sends, fine-tunes, or retrieves against' },
  'M34': { persona: 'Information Security function, with Data Governance, Legal/Contracting, Vendor Management, and the Data Owner', notes: 'Applies both to health-system assets shared with vendors/researchers and to vendor assets shared with the health system (e.g., evaluation sets, prompts). Confirm the sharing channel is covered by contract before use.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Deployment; Termination', responsible: 'Shared — each party controls the channels and agreements for assets it originates' },
  'M71': { persona: 'Privacy & Compliance function, with a qualified statistical expert (internal or contracted), Legal, and Data Governance; often handled through Vendor Management in smaller organizations', notes: 'Qualified experts are typically contracted and costly for as-needed use, which is hard to justify for smaller hospitals; many will rely on vendors or shared/academic partners. Determinations can become a moving target as data and re-identification techniques evolve, hence the reassessment triggers.', solutionTypes: 'Clinical; Operational; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment', responsible: 'Shared — health system (or its contracted expert) issues the determination for its data; vendor documents the determination for data it supplies' },
  'M72': { persona: 'Privacy Engineering (where available) or Data Science function, with Information Security and Privacy & Compliance; typically via Vendor Management for organizations without in-house capability', notes: 'Most hospitals without an academic or tertiary research arm will be unable to implement this in-house; expect reliance on vendors or research partners. Utility trade-offs can be significant when specific questions require boundary conditions or small-cell precision.', solutionTypes: 'Clinical; Operational; Research', lifecycle: 'Pre-deployment; Deployment', responsible: 'Vendor-only in most deployments (implemented within the vendor\'s model/analytics stack); health system only when developing in-house' },
  'M73': { persona: 'Information Security function, with Cloud/Infrastructure, the Data Platform Owner, Data Governance, and the Application Owner', notes: 'For vendor-hosted solutions, confirm tenant isolation and that health-system data is not used to train shared models without explicit agreement. Related to M75 (restricted development environment) and M99 (containment).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Deployment; Monitoring; Termination', responsible: 'Shared — vendor for tenant/environment isolation in hosted products; health system for its own environments and data classification' },
  'M22': { persona: 'Data Engineering / Data Quality function (in many organizations Clinical Informatics, Business Intelligence, Standards & Compliance, or IT/IS), with Data Governance and a Business/Clinical Data Steward', notes: 'For vendor solutions, the health system typically profiles its own input data for fit with the model\'s expectations; the vendor should profile and document training data (see M04, M26).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Piloting', responsible: 'Shared — vendor for training data; health system for local input/validation data' },
  'M36': { persona: 'Data Engineering / Data Quality function, with a Data Steward and the Application or Data Platform Owner', notes: 'Often implemented alongside M39 (missingness checks) and M93 (runtime integrity monitoring). For vendor solutions, confirm what input validation the product performs and what the health system must perform on its interfaces.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor validates inputs within the product; health system validates the data feeds it supplies' },
  'M37': { persona: 'Clinical Informatics, with Data Governance, HIM/Coding, and the Interoperability or Data Standards team', notes: 'HIM/Coding is frequently a co-owner given its role in code assignment and terminology maintenance. Confirm which code systems and versions the vendor model expects and map local data accordingly during implementation.', solutionTypes: 'Clinical; Operational; Administrative; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor declares the standards its model expects; health system maps and maintains its local data to them' },
  'M38': { persona: 'Health Information Management, with Master Patient Index / Identity Management, Data Engineering, and Data Governance', notes: 'Identifier errors compound across systems; this is especially relevant for AI that aggregates data from multiple sources or sites.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Health system-only (enterprise identity management); vendor must consume the reconciled identifiers' },
  'M39': { persona: 'Data Engineering / Data Quality function, with a Data Steward and the Clinical/Business Owner', notes: 'Pair with M76 so decisions about imputing missing values are documented rather than silent.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for within-product handling; health system for completeness of the feeds it supplies' },
  'M40': { persona: 'Data Engineering, with MLOps/AI Engineering, Data Governance, and the Model Owner; for vendor solutions, Vendor Management confirms the vendor\'s practice', notes: 'Smaller hospitals are unlikely to maintain this in-house and will rely on the vendor for versioning; require it in vendor documentation and contracts. Example in practice: one health system expects versioned datasets and validation evidence for higher-risk AI systems so performance can be reproduced, audited, and monitored over time.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for its training/evaluation data and prompts; health system for local validation and retrieval data (small organizations typically rely on vendor)' },
  'M41': { persona: 'Data Quality function, with a Clinical or Operational SME and Data Steward; AI Governance for high-risk use cases', notes: 'Manual review is most valuable where domain context matters (e.g., free text, clinically nuanced fields). Document sample size and selection method (see M66 for output QA).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Monitoring', responsible: 'Health system-only for local data (domain reviewers); vendor for training data review' },
  'M76': { persona: 'Data Science and Data Engineering, with a Data Steward and the Clinical/Business Owner; AI Governance for high-impact use cases', notes: 'The use case is critical here — imputation is frequently a bad idea in clinical decision contexts. Smaller hospitals are unlikely to perform this in-house and will rely on the vendor; ask vendors to disclose imputation methods in model documentation (M04).', solutionTypes: 'Clinical; Operational; Administrative; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for imputation inside its model; health system for any imputation in local pipelines and for accepting the approach' },
  'M79': { persona: 'Data Science, with a Clinical/Operational SME, Clinical Informatics, Data Governance, and the Model Owner', notes: 'Define \'gold standard\' realistically for the use case. Example in practice: one health system has developed synthetic benchmarks for detecting harmful language in free-text notes to evaluate and compare models (see M32).', solutionTypes: 'Clinical; Operational; Administrative; Research', lifecycle: 'Pre-deployment; Piloting; Monitoring', responsible: 'Shared — vendor provides validation evidence; health system builds or curates a local validation set for higher-risk tools' },
  'M80': { persona: 'Data Engineering, with Information Security, Data Science/MLOps, Privacy, and AI Governance', notes: 'For most health systems this applies primarily to locally curated retrieval corpora and fine-tuning sets; for vendor models, request the vendor\'s data-sanitization practices in model documentation (M04) and third-party review (M25).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Monitoring', responsible: 'Shared — vendor for its training data; health system for local fine-tuning/retrieval data' },
  'M18': { persona: 'AI Program Office / AI Governance, with the Clinical or Operational Owner and the frontline care team who will use the tool (e.g., pilot physicians, nurses, or staff), plus a named clinical reviewer', notes: 'Define pilot scope to include explicit safety-monitoring metrics (e.g., escalation accuracy) and a named clinical reviewer. Example in practice: during an ambient documentation (AI scribe) pilot, one health system required pilot providers to send chart identifiers to the Compliance Officer, who reviewed a set number of notes per provider for language and accuracy before approving expansion beyond the pilot (links to M24 and M69). Some prominent organizations are moving away from narrow pilots because of generalizability concerns; treat this as a framework step to consider rather than a universal requirement.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Piloting; Deployment', responsible: 'Health system-only (defines and runs the pilot); vendor supports configuration and provides performance data' },
  'M64': { persona: 'AI Governance, with Information Security, Compliance, and Legal', notes: 'Clarify in the use-case record what is being restricted — the tool\'s capability or information about it — and to whom. Transparency about AI use (M08, M27) remains necessary; this control targets sensitive capabilities, not disclosure of AI use itself.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Deployment', responsible: 'Shared — vendor controls capability release in the product; health system controls what it exposes internally and externally' },
  'M65': { persona: 'IT / Enterprise Architecture, with AI Governance, Clinical Operations, and business/enterprise system owners as needed', notes: 'Narrow \'other systems\' to those the solution actually touches, documented in the integration diagram at intake. Where the assessment identifies propagation paths, pair with M99 (containment) and M100 (fail-safe design). Some respondents note an assessment is evidence for a risk rather than a mitigation in itself; its value is in driving the specific controls that follow.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Deployment', responsible: 'Shared — vendor documents integration points and failure modes; health system assesses impact across its environment' },
  'M99': { persona: 'IT / Enterprise Architecture, with Information Security; often primarily on the vendor for integrated products', notes: 'Respondents cautioned that \'containment/isolation\' reads as an absolute and can undermine the interoperability that clinical and financial operations depend on; prefer terms like sandboxing, guardrails, or limited use. Related controls: M35 (least privilege), M48 (rate limiting), M65 (integration assessment).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for product architecture; health system for integration boundaries and monitoring' },
  'M100': { persona: 'IT / Product Engineering (often the vendor for integrated products), with Clinical Operations and Quality & Safety accountable for the continuity-of-care workflow', notes: 'Documenting the fallback also prevents wasted effort repeating the same failure. Ensure staff know the manual/standard-of-care procedure when the tool is off (see M96, M91).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Shared — vendor designs the product\'s failure behavior; health system owns the continuity-of-operations workflow' },
  'M04': { persona: 'Developer of the model (vendor or internal Data Science / AI Development team) produces it; AI Governance and the Clinical/Operational Owner review it', notes: 'Many model cards in circulation are incomplete; use a standard template (e.g., CHAI Applied Model Card) as the minimum expectation in procurement. Review at intake and re-review on material model changes (see M42, M25).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Monitoring; Termination', responsible: 'Shared — vendor authors for its products; health system authors for internally developed tools and reviews all' },
  'M05': { persona: 'Data Governance / Data Management function (for local data); vendor for training-data documentation', notes: 'This is a foundational data-governance practice that improves consistency, interoperability, and trust. Clarify in each use-case record which data the catalog covers (training data vs. locally ingested data), as respondents found this ambiguous.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Deployment; Monitoring', responsible: 'Shared — health system for local data; vendor for training data (provenance on request)' },
  'M06': { persona: 'Data Science / MLOps (internal tools) or the vendor; AI Governance / AI Program Office for the health system\'s own governance records', notes: 'Recognized MLOps and AI-governance best practice, but several respondents flagged it as aspirational; focus first on versioning the records that support audit (approvals, validation results, change decisions).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Shared — vendor for product documentation; health system for its governance records' },
  'M26': { persona: 'Data Engineering and Data Governance (local pipelines); vendor for upstream lineage', notes: 'Example in practice: one health system uses data-lineage capabilities within its data platform alongside model-tracking tooling to support traceability of access, artifacts, and changes (see M17).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Deployment; Monitoring', responsible: 'Shared — vendor for training-data lineage (on request); health system for local pipelines' },
  'M82': { persona: 'Data Science / Product Engineering (who can run pre- and post-deployment audits), with a Health Equity or Ethics review owner, AI Governance, Compliance, Program Management, and patient/family advisory input (e.g., PFACs)', notes: 'Respondents asked that bias types be broken out more explicitly and that patient/family advisory groups be engaged. Pair with M77/M78 for representativeness and M08 for disclosing known limitations.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Monitoring', responsible: 'Shared — vendor tests and documents for its model; health system tests on its own population and monitors post-deployment' },
  'M01': { persona: 'AI Governance body (e.g., AI Governance Committee, Chief AI Officer, or equivalent executive sponsor); in some organizations IT holds governance ownership', notes: 'This policy relates to all risks rather than one modifier; it is the foundation the other controls reference. Examples in practice: one organization recently finalized a three-level structure (executive/external-facing; a Responsible AI & Data Use steering committee; operating committees) with a charter and is now drafting policies so every use case follows a repeatable process — noting that variability across use cases is itself a risk. Another maintains an official charter, policies, and documented review processes through a Responsible AI Committee, Architecture Board, and Cloud Center of Excellence. Respondents suggested the policy also establish a reporting system for AI safety events and a hub for FAQs, training, and resources for all users.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Health system-only (vendors are subject to it via contract and vendor expectations)' },
  'M02': { persona: 'AI Program Office or AI Governance Committee (who may directly own the inventory), with Clinical Informatics; each organization decides whether it lives in IT, Informatics, Quality, or Risk', notes: 'For internally developed agentic tools, consider a departmental executive-level ownership and approval structure so the governance committee is not bogged down. A central registry that IT and cybersecurity can access supports incident response (see M59).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Health system-only' },
  'M03': { persona: 'Clinical Informatics and Learning & Development, with clinical AI champions (e.g., physician or nurse AI champions) and the Chief AI Officer or equivalent', notes: 'Include training costs in the total-cost-of-ownership analysis at intake. Example in practice: staff who completed structured AI-governance training (e.g., an AI governance professional certification body of knowledge) reported being better able to evaluate clinical AI tools with role-appropriate literacy instead of relying solely on vendor claims. A central hub for FAQs, training, and resources supports adoption (see M01).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — health system owns the program; vendor supplies product-specific training content and limitation disclosures' },
  'M11': { persona: 'Data Governance function (e.g., Chief Data Officer, Data Governance Council, or in smaller organizations the CIO/CMIO)', notes: 'Some respondents rated this lower priority because it is standard data-management practice; its role here is as an enabling foundation that other controls (M09, M22, M26) depend on.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Deployment; Termination', responsible: 'Health system-only' },
  'M20': { persona: 'Clinical Operations and Quality & Safety, with Risk Management for the event-reporting integration', notes: 'Categorization of error and harm level will need to be defined so events route correctly (see M62, M95).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Health system-only (vendor supplies known failure modes to inform the SOP)' },
  'M23': { persona: 'Risk Management and AI Governance, with Compliance and Information Security', notes: 'Framing this as a policy for AI risk management aligns with the risk-assessment methodology expected by standards such as ISO/IEC 42001 and NIST AI RMF.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Monitoring; Termination', responsible: 'Health system-only' },
  'M24': { persona: 'AI Safety / Governance Committee (e.g., AI Oversight Committee, Responsible AI Committee) with licensed clinicians, nursing, quality/safety, compliance, security, and informatics membership', notes: 'Examples in practice: one health system evaluates clinical AI pilots through multidisciplinary review involving nursing, clinical operations, informatics and research leadership, and applicable oversight functions before broader implementation. Another chairs an AI Oversight Committee where much of this mapping is practiced directly. Vendors report parallel structures (Responsible AI committees, architecture boards) that all projects must pass through.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Health system-only' },
  'M25': { persona: 'Vendor Management / Procurement, with Information Security, Privacy/Compliance, Legal, and AI Governance', notes: 'Example in practice: one health system currently relies on a TPRM-adjacent AI review using a standard third-party risk questionnaire; extend this with AI-specific items (model documentation, validation evidence, data use, change management, incident notification).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Monitoring; Termination', responsible: 'Health system-only (vendor supplies evidence and attestations)' },
  'M69': { persona: 'AI Governance Committee, with the Clinical/Operational Owner and Quality & Safety defining the thresholds', notes: 'Example in practice: one health system\'s ambient documentation pilot used a compliance review of a set number of notes per provider as the gate for expansion beyond the pilot (see M18).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Deployment; Termination', responsible: 'Health system-only' },
  'M70': { persona: 'Clinical leadership for the affected disciplines (e.g., CMO/CMIO, CNO/CNIO, pharmacy, allied health leads)', notes: 'Match the approver to the applied environment — a nursing workflow needs nursing leadership sign-off, not only physician leadership (see M43 comment on CMIO vs CNIO).', solutionTypes: 'Clinical; Patient Engagement', lifecycle: 'Pre-deployment; Piloting; Deployment', responsible: 'Health system-only' },
  'M14': { persona: 'Any accountable end-user or owner of the workflow — clinical (frontline clinicians), operational, business, research, or back-office staff', notes: 'Respondents recommended treating M14, M51, M52, and M87 as a family from which the organization selects the appropriate oversight level per function. Agentic and patient-facing AI changes this paradigm; where a human cannot review each output, consider a \'human over the loop\' with system monitoring that triggers alerts (M61, M94).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Health system-only (vendor must design the workflow to support meaningful review)' },
  'M51': { persona: 'Any accountable owner or supervisor of the workflow — clinical, operational, business, research, or back-office', notes: 'Part of the human-oversight family (M14, M51, M52, M87); the organization determines the appropriate level per function. Example in practice: one health system uses AI agents to oversee and analyze agentic patient-facing solutions in production, with humans supervising the monitoring layer.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Health system-only (vendor must expose intervention controls and alerts)' },
  'M52': { persona: 'Any accountable end-user or owner of the workflow — clinical, operational, business, research, or back-office', notes: 'Define \'AI action\' in the use-case record (e.g., writes to the chart, sends a message, places an order, changes a claim). Agentic AI increases the volume of actions; reserve approval steps for consequential ones and rely on M51/M87 for the rest.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Deployment', responsible: 'Shared — health system defines which actions need approval; vendor implements the approval step in the product' },
  'M55': { persona: 'UX / Product Design (usually the vendor), with Clinical Informatics and end-user representatives; smaller systems typically evaluate this at procurement rather than design it', notes: 'Clear design = a design approach that deliberately makes a system\'s limits, uncertainty, and boundaries visible to users rather than hiding them behind a \'seamless\' experience.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Piloting; Deployment', responsible: 'Shared — vendor designs; health system specifies and evaluates at procurement' },
  'M56': { persona: 'Clinical Informatics and the Clinical/Operational Owner, with AI Governance', notes: 'Clarify what is being assessed (context and workflow fit, user competency/training, patient population within validated scope); screening alone is insufficient without defined criteria (see M08).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Deployment', responsible: 'Health system-only (vendor provides intended-use statement)' },
  'M87': { persona: 'Clinical Operations (users) and Product Engineering / IT (system-level stop), with authorized owners named in the SOP', notes: 'Document who can invoke the override, how, and what happens downstream (see M100, M96). Part of the human-oversight family (M14, M51, M52).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor builds the override/stop capability; health system defines who may use it and when' },
  'M88': { persona: 'Clinical Operations and Patient Experience, with Compliance', notes: 'Define \'affected individuals\' in the use-case record (patients, members, applicants, staff). Related to M53 (consent) and M89 (appeal).', solutionTypes: 'Clinical; Patient Engagement; Administrative', lifecycle: 'Risk Assessment; Pre-deployment; Deployment', responsible: 'Health system-only' },
  'M62': { persona: 'Quality & Safety and Risk Management, with MLOps/AI team notified for model errors and Legal or Compliance depending on the nature of the error (billing, safety, research)', notes: 'Provide examples or a scale: an error in a patient message caught before sending is a near miss; cybersecurity incidents and care-delivery incidents should both be in scope but may route differently. Example in practice: one health system routes AI incidents through risk-event reporting and verbal/electronic reports to clinical leadership, IT, quality, and risk management, supported by broad education so events are categorized and escalated; ownership may sit with quality management and the informatics team that inventories all AI. Track hallucination and error rates even when they do not meet the incident threshold (see M83).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Piloting; Deployment; Monitoring; Termination', responsible: 'Shared — health system owns reporting; vendor must report product incidents and cooperate in investigation (contractual)' },
  'M95': { persona: 'Information Security / IT and Quality & Safety jointly, with Risk Management and Legal', notes: 'Example in practice: one health system directs all AI events into its enterprise risk-reporting platform, which permits categorization; that categorization provides the framework for escalation and response timeframes by severity.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Deployment; Monitoring', responsible: 'Shared — health system owns the plan; vendor provides detection signals and incident notification' },
  'M96': { persona: 'IT / Business Continuity, with Clinical Operations for the manual workflow', notes: 'Distinct from M95: M95 responds to a discrete incident; M96 addresses system-level failure or unavailability and depends on how deeply the AI is integrated into other technologies. Example: if an ambient documentation tool is unavailable, clinicians revert to standard documentation and the outage is communicated; if a triage agent is suspended, calls route to the standard human queue.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Deployment; Monitoring; Termination', responsible: 'Shared — vendor for service recovery; health system for continuity of its workflows' },
  'M15': { persona: 'MLOps / IT (internal tools) or the vendor, with AI Governance receiving change notifications for higher-risk tools', notes: 'Respondents note there are not yet mature industry standards for AI change-management tracking; a simple change record is a practical baseline. Example in practice: one health system maintains controlled lifecycle processes tracking model versions, configuration changes, approvals, and deployment history, with changes documented and reviewed through governance to support auditability and safe operation.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Shared — vendor for product versions; health system for local configuration and for receiving/reviewing change notices' },
  'M16': { persona: 'Software Engineering / IT (internal tools) or the vendor; largely a background technical control', notes: 'Some respondents felt this is too technical for the mapping; it is retained because prompt/harness drift is a common and under-tracked source of behavior change in generative and agentic tools.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for its code/prompts; health system for anything it builds or configures (prompts, integrations)' },
  'M57': { persona: 'MLOps / Data Science (internal tools) with IT / Enterprise Digital Services, under AI Governance; the vendor for its own lifecycle', notes: 'Example in practice: one organization uses version control and controlled CI/CD promotion across development, test, and production, with approvals required before changes move into production.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Shared — vendor for product lifecycle; health system for acquisition, approval, local validation, monitoring, and retirement' },
  'M58': { persona: 'MLOps / Data Science (internal) or the vendor for retraining; AI Governance, Information Security, and the Clinical/Operational Owner for revalidation and approval', notes: 'Some advanced tools (e.g., robotics) may update frequently; agree on notification and revalidation expectations with the vendor in the contract (M25). Link to vendor documentation rather than duplicating.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring', responsible: 'Shared — vendor retrains its models; health system revalidates locally and approves reuse' },
  'M59': { persona: 'MLOps or the AI Program Office (each organization decides whether this lives in IT, Informatics, Quality, or Risk), with Information Security access', notes: 'Closely related to the AI inventory (M02); many organizations combine them. Example in practice: one health system is centralizing all production models into a single repository for reporting, dashboards, and alerting.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Health system-only (vendor supplies version information)' },
  'M90': { persona: 'MLOps / IT (internal) or the vendor for hosted products, with the AI Program Office deciding rollout approach', notes: 'Some respondents view this as a temporary control that reduces severity during a release window rather than an enduring mitigation; it is most useful when paired with monitoring (M60) and rollback (M91).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring', responsible: 'Shared — vendor controls release mechanics; health system decides scope/sequence of local rollout' },
  'M91': { persona: 'MLOps / IT (internal) or the vendor, with Information Security notified and Clinical Operations owning the manual fallback', notes: 'Rollback enables rapid restoration of a stable state when a deployed system shows unsafe, inaccurate, or unexpected behavior; test it before go-live (see M100, M96).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring; Termination', responsible: 'Shared — vendor provides rollback capability; health system defines when to invoke it and the non-AI fallback' },
  'M12': { persona: 'Data Science / ML Engineering (or the vendor), with Clinical Informatics defining the required fields and vocabularies', notes: 'This mitigation is most practical for tools with defined tasks (e.g., extraction, classification, structured summaries); less so for open-ended conversational or multimodal tools.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment', responsible: 'Shared — vendor designs schemas; health system specifies local vocabularies and interface formats' },
  'M13': { persona: 'Data Science / ML Engineering (or the vendor), with the Clinical/Operational Owner defining scope constraints and AI Governance approving them', notes: 'Example in practice: one health system deployed a patient-facing agent that answers clinical questions with access to the patient\'s record, with a hard constraint that behavioral-health questions are not answered given the risk level — and the patient is told so. Pair prompt constraints with M44/M45/M49 for enforcement.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor implements; health system defines scope and approves constraints' },
  'M43': { persona: 'Data Science, with the clinical leadership relevant to the applied environment (e.g., CMIO for physician workflows, CNIO for nursing workflows) and Quality & Safety', notes: 'Requires adequate local analytics capacity; for predictive models of clinical outcomes, recommend discrimination and calibration data rather than accuracy alone.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Piloting; Monitoring', responsible: 'Shared — vendor reports performance; health system sets acceptance thresholds for its context' },
  'M44': { persona: 'ML Engineering / Platform Engineering (or the vendor), with Information Security', notes: 'Example in practice: one health system requires all agentic AI requests to be routed through an approved API gateway that associates each interaction with an authenticated user identity, enabling end-to-end traceability, policy enforcement, monitoring, and detection of misuse or anomalous behavior.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for in-product guardrails; health system for gateway/perimeter controls' },
  'M45': { persona: 'ML Engineering (or the vendor), with Quality & Safety or Clinical Informatics defining output rules', notes: 'Example in practice: one organization requires all AI projects to run through a governance/evaluation tool that checks inputs, outputs, accuracy, and custom tests, with logging to show the testing occurred.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor implements; health system defines rules and audits' },
  'M46': { persona: 'Data Science (or the vendor), with clinical leadership engaged so that explainability is valued and requested during vendor selection', notes: 'Easier to promote for internal development than to require of vendors; involve clinical leadership early so explainability becomes a default procurement expectation.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment', responsible: 'Shared — vendor\'s model design; health system\'s procurement preference and compensating controls' },
  'M47': { persona: 'ML Engineering / Data Science (or the vendor), with content owners (e.g., clinical policy, pharmacy, or knowledge-management leads) responsible for source currency; same personas as M58 given the parallels', notes: 'Retrieved content and generated outputs both require validation (M45, M83). At minimum, review whether new or updated sources are available on a set schedule.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for retrieval mechanics; health system for the content corpus and its currency' },
  'M49': { persona: 'ML Engineering (or the vendor), with Compliance and the Clinical/Operational Owner defining the prohibited-content policy', notes: 'Distinguished from M44/M45 by focus: those validate form and correctness; this targets harmful or prohibited content. Example: synthetic benchmarks for harmful language in free text (M32) can be used to test these filters.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor implements filters; health system defines policy and tests' },
  'M50': { persona: 'Data Science / MLOps (or the vendor), with AI Governance and clinical leadership for higher-risk tools', notes: 'Overlaps with governance and change management (M15); several respondents suggested it could sit under governance. For vendor products this is largely informational — request disclosure of safety-relevant settings (e.g., temperature, thresholds).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor controls model settings; health system reviews/approves any exposed configuration' },
  'M81': { persona: 'Clinical Informatics / Clinical Validation team with Data Science (or a dedicated model-ops team); clinician reviewers for clinical evaluation', notes: 'Examples in practice: one health system has a model-ops team that validates and tests models for fit-for-purpose, drift, and validation; a vendor evaluates outputs against trusted evidence-based guidelines using combined AI-assisted and clinician review; another health system performs this for internally developed tools.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting', responsible: 'Shared — vendor provides independent validation evidence; health system performs local validation proportionate to risk' },
  'M83': { persona: 'ML Engineering (or the vendor), with Quality & Safety tracking rates and incidents', notes: 'Hallucinations that do not meet the incident threshold should still be measured (e.g., accuracy and hallucination rate per release). Considered a specialization of output guardrails (M45); the title is retained because respondents wanted the generative-AI risk named explicitly.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor implements detection; health system measures rates and reports incidents' },
  'M84': { persona: 'Data Science / ML Engineering (or the vendor), with Clinical Informatics', notes: 'Example in practice: one health system uses AI agents to oversee and analyze agentic patient-facing solutions in production (see M51).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor may build in; health system may add an independent verification layer' },
  'M85': { persona: 'Data Science (or the vendor), with the validation team', notes: 'Applies equally to multi-agent workflows where agents chain outputs; see M65 for additive integration risk.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Monitoring', responsible: 'Vendor-only in most deployments (model architecture); health system validates the combined system' },
  'M17': { persona: 'Information Security / IT, with Compliance, AI Governance, and clinical or quality/safety stakeholders who need to review logs', notes: 'Example in practice: one health system uses system-access audit tables and logging within its data platform, together with model-tracking tooling and data-lineage capabilities, to support traceability of access, model artifacts, and changes. Another associates every agentic call with a unique agent identity plus the requesting user ID via an API gateway (see M29).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Shared — vendor logs its platform; health system logs its environment and defines what vendor logs it needs access to' },
  'M60': { persona: 'MLOps / Data Science (or a model-ops team) for the technical monitoring, with a named clinical owner, Quality & Safety, AI Governance, and impacted clinical departments alerted as needed', notes: 'Examples in practice: one health system has a model-ops team validating models for fit-for-purpose and drift; another uses model-tracking tooling for performance and is developing drift monitoring, incorporating performance, drift, and bias into a broader AI tracking approach. Define the parameters to be monitored per use case — drift may not be easy to detect without them.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Piloting; Deployment; Monitoring', responsible: 'Shared — vendor monitors its model and notifies of changes; health system monitors local performance and owns the clinical decision' },
  'M61': { persona: 'MLOps / IT (or the vendor for hosted monitoring), with the clinical owner and Quality & Safety consuming the outputs', notes: 'Example in practice: one health system is centralizing all production models into one repository for reporting, dashboards, and alerting; another uses AI agents to monitor agentic patient-facing solutions in production.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring', responsible: 'Shared — vendor may provide monitoring tooling; health system configures and reviews it' },
  'M92': { persona: 'MLOps / IT Operations and Information Security (or the vendor), with the clinical owner for response decisions', notes: 'Several respondents suggested rolling this into general model monitoring (M60/M61) since most monitoring in practice is asynchronous; it is retained as the higher-risk tier. \'Emergent issues\' means behaviors not anticipated at validation (e.g., new failure modes after an upstream change).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring', responsible: 'Shared — vendor for its platform\'s security/performance telemetry; health system for integration into its monitoring and response' },
  'M93': { persona: 'Data Engineering and Information Security (or the vendor), with the data platform owner', notes: '', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring', responsible: 'Shared — vendor for data inside its platform; health system for the feeds it supplies' },
  'M94': { persona: 'IT Operations and Information Security, with MLOps; for higher tiers, hospital administration and impacted department leaders for alerting and awareness, plus clinical, quality/safety, and AI Governance stakeholders', notes: 'Tie tiers to the incident severity scale defined in M62/M95 so alerts and incidents share one taxonomy.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring', responsible: 'Shared — vendor emits alerts; health system defines tiers, routing, and suspension rules' },
  'M53': { persona: 'Compliance & Privacy function with Legal, the clinical or operational owner, and Patient Experience; Research/IRB when the AI is investigational', notes: 'Distinguish consent required for legal reasons from transparency/awareness that AI is part of care operations; investigational AI triggers research-consent requirements. Where opt-out is impossible, disclose that in the consent-to-treat materials. The appropriate approach differs sharply between, for example, an ambient AI scribe and population-health analytics.', solutionTypes: 'Clinical; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Deployment', responsible: 'Health system-only (vendor must support disclosure/opt-out features in the product)' },
  'M54': { persona: 'Patient Experience and Clinical Operations, with the AI Program Office closing the loop and Quality & Safety for issue-type feedback', notes: 'The intent of this risk mitigation is issue reporting and structured input, with feedback that rises to the level of an incident routed to M62. Example in practice: one health system runs an audit process with vendors and internal IT and conducts stakeholder surveys to collect feedback and plan mitigation strategies.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Piloting; Deployment; Monitoring', responsible: 'Shared — health system owns channels and governance; vendor provides in-product feedback capture and acts on product issues' },
  'M77': { persona: 'Data Science (or the vendor) with Health Equity / Population Health subject-matter experts and Clinical Informatics', notes: 'For rare diseases and small populations, most datasets will not contain enough samples to fully resolve representativeness; document the limitation and rely on M78, M08, and post-deployment monitoring (M60). Provide clear guidance on how this applies to third-party models (evidence review rather than data collection).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment', responsible: 'Shared — vendor collects/documents training data; health system reviews evidence of fit for its population' },
  'M78': { persona: 'Data Science (or the vendor) with Health Equity / Population Health SMEs, Clinical Informatics, and AI Governance', notes: 'This analysis is evidence that informs the likelihood of a risk more than it reduces it directly; its value is in triggering M82, M08, and monitoring actions. Example in practice: one health system checks representativeness but usually must acknowledge its absence because vendor sample datasets are small to begin with.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Risk Assessment; Pre-deployment; Piloting; Monitoring', responsible: 'Shared — vendor reports subgroup performance; health system analyzes on its own population' },
  'M35': { persona: 'Information Security / IAM, with the application owner and AI Governance', notes: 'Example in practice: one health system uses role-based and least-privilege access controls, including directory groups and approval-based access, to limit access to AI and data-platform resources. Related to M10 (user access) and M99 (containment).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring; Termination', responsible: 'Shared — vendor designs minimal permission requirements; health system grants and reviews them' },
  'M48': { persona: 'IT / Platform Engineering (or the vendor), with Information Security', notes: 'Not needed for every use case; most relevant to agentic, API-driven, and patient-facing conversational tools.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Deployment; Monitoring', responsible: 'Shared — vendor for platform limits; health system for gateway limits and usage review' },
  'M63': { persona: 'Information Security (or the vendor for hosted components)', notes: 'Include AI-specific components (model-serving infrastructure, vector databases, agent frameworks, plugins) in the scanning scope, not only traditional infrastructure.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Deployment; Monitoring', responsible: 'Shared — vendor scans its platform; health system scans its own environment and integrations' },
  'M74': { persona: 'Information Security (or the vendor), with Cloud/Infrastructure', notes: 'Some respondents question the general usefulness of this control for health systems that do not host models; treat it as applicable primarily to internally hosted or proprietary models.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Deployment', responsible: 'Vendor-only for hosted models; health system only when self-hosting' },
  'M75': { persona: 'IT / Information Security (internal development) or the vendor with third-party assurance', notes: 'Example in practice: one health system\'s MLOps process uses version control and controlled CI/CD promotion across development, test, and production, with approvals required before changes move into production.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting', responsible: 'Health system-only for internal development; vendor-only for vendor products (verified via assurance)' },
  'M86': { persona: 'Information Security / ML Engineering (or the vendor)', notes: 'Primarily applies to generative and agentic AI; include injection scenarios in red-team testing (M97).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor for model/product defenses; health system for retrieval sources and integration testing' },
  'M97': { persona: 'Information Security, with clinical, quality/safety, and AI Governance stakeholders designing scenarios; often a third party or the vendor for organizations without in-house capability', notes: 'Many organizations cannot perform this in-house. Example in practice: one health system has used adversarial and edge-case testing on patient-facing AI experiences — off-topic, override, and safety-sensitive scenarios — to identify failure modes and improve responses. Another is building a dedicated team to expand testing for malicious or harmful attacks on its AI systems.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Monitoring', responsible: 'Shared — vendor tests its product; health system tests its configured deployment proportionate to risk' },
  'M98': { persona: 'Information Security (internal or contracted testers), with IT and the vendor for hosted components', notes: 'Most organizations lack a standing penetration-testing team, and enterprise tests may not cover the infrastructure touching AI; scope AI components explicitly. Example in practice: one health system performs periodic information-security validation that includes penetration testing and research into known issues.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Deployment; Monitoring', responsible: 'Shared — vendor for its hosted surface; health system for its integrations and environment' },
  'M19': { persona: 'Software Engineering / Data Science (or the vendor), with a human reviewer of test results', notes: 'Applies to integration and configuration code the health system owns even when the model is vendor-supplied.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Deployment; Monitoring', responsible: 'Shared — vendor for product code; health system for its integration/configuration code' },
  'M66': { persona: 'Quality Assurance / Quality & Safety and Clinical Operations, with clinical or domain reviewers', notes: 'Example in practice: an ambient documentation pilot required compliance review of a set number of notes per provider before expansion (see M18). Another organization audits AI outputs in collaboration with vendors and internal IT.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Health system-only (vendor may supply sampling tools and reference outputs)' },
  'M67': { persona: 'Data Science / Data Annotation team (or the vendor), with clinical or domain SMEs as annotators', notes: 'Applies both to vendor training labels (request inter-rater statistics in model documentation) and to local validation datasets (M79).', solutionTypes: 'Clinical; Operational; Administrative; Research', lifecycle: 'Pre-deployment; Piloting', responsible: 'Shared — vendor for training labels; health system for local validation labels' },
  'M68': { persona: 'Data Science, with clinical leadership, Quality (to align to recognized standards), and AI Governance selecting benchmarks, comparators, and subgroups', notes: '\'Prior workflow\' means comparing the AI-supported process to how the task was performed before (e.g., manual triage) so improvement or regression is measurable. Example in practice: one organization\'s science team relies heavily on benchmark tests and is expected to speak to results, implications, risks, and differences across testing scenarios, supported by a governance tool that automates evaluation and logs that testing occurred.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Piloting; Monitoring', responsible: 'Shared — vendor provides benchmark evidence; health system benchmarks against its own workflow and population' },
  'M08': { persona: 'AI Governance / Compliance, with the vendor supplying the intended-use statement and the clinical/operational owner communicating it to users', notes: 'Residual-risk reporting at the use level can be as simple as the known failure modes and the mitigations in place, drawn from the risk assessment (M23).', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Pre-deployment; Deployment; Monitoring', responsible: 'Shared — vendor discloses intended use/limitations; health system discloses residual risk and enforces scope' },
  'M27': { persona: 'Clinical Informatics / IT (EHR build) with the vendor, and Compliance for disclosure policy', notes: 'In an EHR, persistent marking is typically metadata or standardized text (e.g., a smart-text attestation) rather than a visual watermark. Use-case dependent — the label should be appropriate to the content and audience.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Pre-deployment; Piloting; Deployment; Monitoring', responsible: 'Shared — vendor emits provenance; health system configures how it persists in its records' },
  'M28': { persona: 'Data Science / Clinical Informatics (or the vendor), with end-user representatives defining what explanation is useful', notes: 'Related to M46 (interpretable models) and M55 (surfacing uncertainty). Example: a citation list for a generated summary; top contributing features for a risk score.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Pre-deployment; Piloting; Deployment', responsible: 'Shared — vendor provides explanation features; health system specifies and validates usefulness' },
  'M42': { persona: 'Data Science / Data Governance, with Vendor Management and Legal for licensing and contractual disclosure', notes: 'For health systems acquiring rather than building, licensing and collection context are largely questions to ask vendors (M25); for locally curated data (e.g., retrieval corpora) they apply directly.', solutionTypes: 'Clinical; Operational; Administrative; Patient Engagement; Research', lifecycle: 'Intake/Procurement; Risk Assessment; Monitoring', responsible: 'Shared — vendor discloses provenance to the extent it can; health system verifies local sources' },
}
